const routes=[
{id:'r-3000-0',pref:P,areas:[A.saga],title:T('사가성 역사와 벌룬 문화 반나절','佐賀城の歴史とバルーン文化 半日'),duration:T('반나절','半日'),intro:T('사가성 혼마루 역사관과 벌룬 뮤지엄을 연결해 도시의 역사와 현대 축제 문화를 함께 보는 일정입니다.','佐賀城本丸歴史館とバルーンミュージアムをつなぎ、都市の歴史と現代の祭り文化を一緒に見るコースです。'),note:T('두 시설 모두 사가 시내에 있어 버스나 도보로 연결하기 쉽습니다.','両施設とも佐賀市内にあり、バスや徒歩でつなぎやすいです。'),days:[{label:A.saga,places:[3000,3001],schedule:[[3000,'09:30',places.find(p=>p.id===3000).activity],[null,'11:30',T('사가 시내에서 점심·이동','佐賀市内で昼食・移動')],[3001,'13:00',places.find(p=>p.id===3001).activity]]}],image:''},
{id:'r-3000-1',pref:P,areas:[A.saga],title:T('요시노가리 역사공원 하루','吉野ヶ里歴史公園 1日'),duration:T('1일','1日'),intro:T('야요이시대 대규모 환호취락을 복원 건축과 체험 프로그램으로 깊게 보는 역사 중심 일정입니다.','弥生時代の大規模環壕集落を復元建築と体験プログラムでじっくり見る歴史中心のコースです。'),note:T('공원이 넓으므로 보고 싶은 구역과 체험 시간을 먼저 정하고 편한 신발을 준비하세요.','公園が広いため、見たいエリアと体験時間を先に決め、歩きやすい靴を用意してください。'),days:[{label:A.saga,places:[3002],schedule:[[3002,'10:00',places.find(p=>p.id===3002).activity],[null,'13:00',T('공원 내·주변에서 점심·휴식','公園内・周辺で昼食・休憩')],[3002,'14:00',T('오후에는 오전에 못 본 복원 취락과 체험 구역을 이어서 둘러보세요.','午後は午前に見られなかった復元集落や体験エリアを続けて巡ってください。')]]}],image:''},
{id:'r-3000-2',pref:P,areas:[A.kara],title:T('가라쓰성과 니지노마쓰바라 하루','唐津城と虹の松原 1日'),duration:T('1일','1日'),intro:T('가라쓰의 대표 성곽과 해안 송림을 하루에 묶는 도심·자연 기본 일정입니다.','唐津を代表する城郭と海岸松林を1日にまとめる市街・自然の基本コースです。'),note:T('가라쓰역을 거점으로 성과 송림 사이를 JR·버스·택시로 조정하세요.','唐津駅を拠点に、城と松原の間をJR・バス・タクシーで調整してください。'),days:[{label:A.kara,places:[3003,3004],schedule:[[3003,'09:30',places.find(p=>p.id===3003).activity],[null,'12:00',T('가라쓰 시내에서 점심·이동','唐津市内で昼食・移動')],[3004,'13:30',places.find(p=>p.id===3004).activity]]}],image:''},
{id:'r-3000-3',pref:P,areas:[A.kara],title:T('요부코 시장과 나나쓰가마 하루','呼子朝市と七ツ釜 1日'),duration:T('1일','1日'),intro:T('오전 시장과 오징어 식사 뒤 해안 절경과 유람선을 즐기는 요부코 대표 일정입니다.','朝市とイカ料理の後、海岸絶景と遊覧船を楽しむ呼子の代表コースです。'),note:T('아침시장은 오전이 핵심이고 유람선은 파도에 따라 결항할 수 있으므로 순서를 고정하지 말고 현장 상황에 맞추세요.','朝市は午前が中心で、遊覧船は波で欠航する場合があるため、順序を固定せず現地状況に合わせてください。'),days:[{label:A.kara,places:[3006,3005],schedule:[[3006,'08:30',places.find(p=>p.id===3006).activity],[null,'11:00',T('요부코에서 오징어 점심','呼子でイカの昼食')],[3005,'13:00',places.find(p=>p.id===3005).activity]]}],image:''},
{id:'r-3000-4',pref:P,areas:[A.kara],title:T('히젠 나고야성과 요부코 역사·항구 하루','肥前名護屋城と呼子 歴史・港 1日'),duration:T('1일','1日'),intro:T('16세기 말 대규모 성터의 역사와 오늘날 요부코 항구 문화를 함께 보는 일정입니다.','16世紀末の大規模城跡の歴史と、現代の呼子港文化を一緒に見るコースです。'),note:T('나고야성터와 요부코 사이 버스 편수를 확인하고 박물관 휴관일도 미리 확인하세요.','名護屋城跡と呼子間のバス本数を確認し、博物館の休館日も事前に確認してください。'),days:[{label:A.kara,places:[3007,3006],schedule:[[3007,'09:30',places.find(p=>p.id===3007).activity],[null,'12:30',T('요부코로 이동·점심','呼子へ移動・昼食')],[3006,'14:00',T('오후에는 항구와 시장 주변 상점·건어물 가게를 여유롭게 둘러보세요.','午後は港や朝市周辺の店舗、干物店をゆっくり巡ってください。')]]}],image:''},
{id:'r-3000-5',pref:P,areas:[A.ari],title:T('아리타 도자기 문화 하루','有田の陶磁文化 1日'),duration:T('1일','1日'),intro:T('규슈도자문화관에서 아리타야키 역사를 이해한 뒤 도잔 신사와 옛 도자기 거리를 걷는 일정입니다.','九州陶磁文化館で有田焼の歴史を学んだ後、陶山神社と古い焼き物の町並みを歩くコースです。'),note:T('도자기시장 기간에는 매우 혼잡하므로 열차 이동과 상점 영업시간을 여유 있게 잡으세요.','陶器市期間は非常に混雑するため、鉄道移動と店舗営業時間に余裕を持ってください。'),days:[{label:A.ari,places:[3008,3009],schedule:[[3008,'10:00',places.find(p=>p.id===3008).activity],[null,'12:00',T('아리타역·우치야마 지구에서 점심','有田駅・内山地区で昼食')],[3009,'13:30',places.find(p=>p.id===3009).activity]]}],image:''},
{id:'r-3000-6',pref:P,areas:[A.ari],title:T('오카와치야마 도자기마을 반나절','大川内山の焼き物の里 半日'),duration:T('반나절','半日'),intro:T('산으로 둘러싸인 비요의 마을에서 가마·갤러리·도자기 다리를 천천히 둘러보는 일정입니다.','山に囲まれた秘窯の里で、窯元、ギャラリー、陶板の橋をゆっくり巡るコースです。'),note:T('버스 편수가 많지 않을 수 있으므로 이마리역 귀환 시간을 먼저 확인하세요.','バス本数が多くない場合があるため、伊万里駅への帰りの時刻を先に確認してください。'),days:[{label:A.ari,places:[3010],schedule:[[3010,'10:00',places.find(p=>p.id===3010).activity],[null,'12:30',T('오카와치야마에서 점심·도자기 쇼핑','大川内山で昼食・器の買い物')]]}],image:''},
{id:'r-3000-7',pref:P,areas:[A.take],title:T('다케오 온천과 미후네야마 하루','武雄温泉と御船山 1日'),duration:T('1일','1日'),intro:T('다케오의 근대 온천 건축과 대정원, 거목 신앙을 한 도시에서 함께 즐기는 일정입니다.','武雄の近代温泉建築、大庭園、巨木信仰を一つの街で一緒に楽しむコースです。'),note:T('미후네야마 봄·가을 성수기에는 야간 공개가 있어 방문 순서를 계절에 맞춰 바꿔도 좋습니다.','御船山の春・秋の繁忙期は夜間公開があるため、季節に合わせて訪問順を変えてもよいでしょう。'),days:[{label:A.take,places:[3011,3013,3012],schedule:[[3011,'09:30',places.find(p=>p.id===3011).activity],[3013,'11:30',places.find(p=>p.id===3013).activity],[null,'13:00',T('다케오에서 점심·이동','武雄で昼食・移動')],[3012,'14:00',places.find(p=>p.id===3012).activity]]}],image:''},
{id:'r-3000-8',pref:P,areas:[A.ure,A.kashi],title:T('우레시노 온천과 유토쿠 이나리 하루','嬉野温泉と祐徳稲荷 1日'),duration:T('1일','1日'),intro:T('사가 남부의 대표 온천과 대형 이나리 신사를 하루에 묶는 휴양·신앙 일정입니다.','佐賀南部を代表する温泉と大規模な稲荷神社を1日にまとめる休養・信仰コースです。'),note:T('두 지역 사이 대중교통은 환승이 필요할 수 있어 버스 시간을 먼저 확인하거나 택시를 고려하세요.','2地域間の公共交通は乗り継ぎが必要な場合があるため、バス時刻を先に確認するかタクシーを検討してください。'),days:[{label:T('우레시노·가시마','嬉野・鹿島'),places:[3014,3015],schedule:[[3014,'09:30',places.find(p=>p.id===3014).activity],[null,'12:00',T('우레시노에서 온천유두부 점심·이동','嬉野で温泉湯どうふの昼食・移動')],[3015,'13:30',places.find(p=>p.id===3015).activity]]}],image:''},
{id:'r-3000-9',pref:P,areas:[A.kashi,A.tara],title:T('히젠하마와 아리아케해 하루','肥前浜と有明海 1日'),duration:T('1일','1日'),intro:T('전통 양조장 거리와 아리아케해의 큰 조수간만 차가 만드는 해안 풍경을 함께 보는 일정입니다.','伝統的な酒蔵通りと、有明海の大きな干満差が生む海岸景観を一緒に見るコースです。'),note:T('해중 도리이 풍경은 조석 시간에 따라 크게 달라지므로 조석표를 기준으로 일정을 역순으로 바꿔도 좋습니다.','海中鳥居の景観は潮汐時刻で大きく変わるため、潮汐表を基準に予定を逆順にしてもよいでしょう。'),days:[{label:T('가시마·다라','鹿島・太良'),places:[3016,3017],schedule:[[3016,'10:00',places.find(p=>p.id===3016).activity],[null,'12:30',T('가시마·다라에서 점심·이동','鹿島・太良で昼食・移動')],[3017,'14:30',places.find(p=>p.id===3017).activity]]}],image:''}
];
